get_checkout_page.code:
import (
	"fmt"
)

resp, err := client.CheckoutPageSettings().GetCheckoutPage(ctx, nil, nil)
if err != nil {
	log.Fatal(err)
}
settings := resp.Map().(map[string]any)["checkout_page"].(map[string]any)
checkout := settings["customer_checkout"].(map[string]any)
summary := settings["order_summary"].(map[string]any)
fmt.Println(checkout["allow_sign_in"], checkout["multiple_shipping_methods"], summary["enable_payment_expand_view"])

patch_checkout_page.code:
import (
	"fmt"
)

resp, err := client.CheckoutPageSettings().PatchCheckoutPage(ctx, map[string]any{
	"checkout_page": map[string]any{
		"order_summary":     map[string]any{"enable_payment_expand_view": false},
		"customer_checkout": map[string]any{"multiple_shipping_methods": true},
	},
}, nil)
if err != nil {
	log.Fatal(err)
}
settings := resp.Map().(map[string]any)["checkout_page"].(map[string]any)
fmt.Println(settings["order_summary"].(map[string]any)["enable_payment_expand_view"], settings["customer_checkout"].(map[string]any)["multiple_shipping_methods"])

